dtsPropsFor.AgentCard:
/** The agent to render. The tile links to /agents/$id itself. */
agent: {
  id: string;
  name: string;
  description: string;
  version: string;
  hostname: string;
  status: 'online' | 'offline';
  last_seen_at?: string;
  created_at: string;
  cpu_usage_percent?: number;
  memory_used_bytes?: number;
  memory_total_bytes?: number;
  disk_used_bytes?: number;
  disk_total_bytes?: number;
  running_containers?: number;
};

dtsPropsFor.RadialGauge:
/** Usage percentage, clamped to 0-100. Colour slides green (low) to red (high). */
percent: number;
/** Caption under the ring. */
label: string;
/** Optional secondary caption. */
sublabel?: string;

dtsPropsFor.StatRow:
/** Left-hand caption. */
label: string;
/** Right-hand value, rendered monospace. */
value: string;

dtsPropsFor.DetailRow:
/** Left-hand caption. */
label: string;
/** Right-hand value, rendered monospace and truncated. */
value: string;
/** When set, the value becomes an anchor with this href. */
link?: string;

dtsPropsFor.Field:
/** Label text rendered above the control. */
label: string;
/** Dim helper text rendered below the control. */
hint?: string;
/** Appends a red asterisk to the label. */
required?: boolean;
/** The form control this label wraps. */
children: React.ReactNode;

dtsPropsFor.Input:
/** Current value (controlled). */
value: string;
/** Receives the new string value, not the change event. */
onChange: (v: string) => void;
placeholder?: string;
required?: boolean;
/** Render in a monospace face — for image refs, commands and env values. */
mono?: boolean;
/** Passed through to the underlying input. Defaults to 'text'. */
type?: string;

dtsPropsFor.LogViewer:
/** Log lines in sequence order. */
lines: Array<{
  line: string;
  stream: 'stdout' | 'stderr';
  sequence: number;
  timestamp: string;
}>;
/** Shows the pulsing "live" indicator in the header. */
live: boolean;

dtsPropsFor.Card:
/** Card and its parts (CardHeader, CardTitle, CardDescription, CardAction, CardContent, CardFooter) are plain divs. */
className?: string;
children?: React.ReactNode;
/** Plus all standard <div> attributes. */
[key: string]: unknown;

dtsPropsFor.ChartContainer:
/** Maps each dataKey to its label and colour. `theme` sets per-mode colours. */
config: Record<string, {
  label?: React.ReactNode;
  icon?: React.ComponentType;
  color?: string;
  theme?: Record<'light' | 'dark', string>;
}>;
/** A single recharts element, e.g. <AreaChart> or <RadialBarChart>. */
children: React.ReactElement;
/** Size the chart here (e.g. "h-24 w-full"), never via recharts width/height. */
className?: string;
id?: string;
initialDimension?: { width: number; height: number };

dtsPropsFor.Tooltip:
/** Tooltip must render inside a TooltipProvider. Compose with TooltipTrigger and TooltipContent. */
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/** Delay before opening, in ms. TooltipProvider defaults it to 0. */
delayDuration?: number;
children?: React.ReactNode;
